const assert = require('node:assert');
const { resolveSession } = require('/workspace/src/session.js');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  // 1. Sequential caching: same io + session => one load, same object.
  {
    let calls = 0;
    const io = { tenantId: 'A', loadSession: async (id) => ({ id, n: ++calls, tenant: 'A' }) };
    const a = await resolveSession(io, 's1');
    const b = await resolveSession(io, 's1');
    assert.strictEqual(calls, 1, 'sequential cache hit');
    assert.strictEqual(a, b, 'same cached object');
  }

  // 2. Concurrent thundering herd: same io + session => one load.
  {
    let calls = 0;
    const io = {
      tenantId: 'A',
      loadSession: async (id) => { calls++; await sleep(20); return { id }; },
    };
    const [a, b, c] = await Promise.all([
      resolveSession(io, 's2'),
      resolveSession(io, 's2'),
      resolveSession(io, 's2'),
    ]);
    assert.strictEqual(calls, 1, 'concurrent dedup');
    assert.strictEqual(a, b);
    assert.strictEqual(b, c);
  }

  // 3. Same io object, different tenants, same session id => isolated.
  {
    const loads = [];
    const io = {
      tenantId: 'A',
      loadSession: async (id) => { loads.push(io.tenantId); return { id, tenant: io.tenantId }; },
    };
    const a = await resolveSession(io, 'shared');
    io.tenantId = 'B';
    const b = await resolveSession(io, 'shared');
    assert.strictEqual(a.tenant, 'A');
    assert.strictEqual(b.tenant, 'B');
    assert.deepStrictEqual(loads, ['A', 'B']);
  }

  // 4. Different io contexts, same session id => isolated.
  {
    const ioA = { tenantId: 'A', loadSession: async () => ({ tenant: 'A' }) };
    const ioB = { tenantId: 'B', loadSession: async () => ({ tenant: 'B' }) };
    assert.strictEqual((await resolveSession(ioA, 'x')).tenant, 'A');
    assert.strictEqual((await resolveSession(ioB, 'x')).tenant, 'B');
    assert.strictEqual((await resolveSession(ioA, 'x')).tenant, 'A');
  }

  // 5. Failure is not cached; next call retries.
  {
    let calls = 0;
    const io = {
      tenantId: 'A',
      loadSession: async () => {
        calls++;
        if (calls === 1) throw new Error('boom');
        return { ok: true };
      },
    };
    await assert.rejects(() => resolveSession(io, 'f'), /boom/);
    const ok = await resolveSession(io, 'f');
    assert.deepStrictEqual(ok, { ok: true });
    assert.strictEqual(calls, 2, 'failure evicted and retried');
  }

  // 6. Synchronous throw and resolved undefined.
  {
    let calls = 0;
    const io = {
      loadSession: () => {
        calls++;
        if (calls === 1) throw new Error('sync');
        return undefined;
      },
    };
    await assert.rejects(() => resolveSession(io, 'g'), /sync/);
    const v = await resolveSession(io, 'g');
    assert.strictEqual(v, undefined);
    assert.strictEqual(calls, 2);
  }

  // 7. Different sessions on same context are independent.
  {
    const seen = [];
    const io = { tenantId: 'A', loadSession: async (id) => { seen.push(id); return { id }; } };
    await Promise.all([resolveSession(io, 'p'), resolveSession(io, 'q')]);
    assert.deepStrictEqual([...seen].sort(), ['p', 'q']);
  }

  console.log('ALL SESSION TESTS PASSED');
})().catch((e) => { console.error('TEST FAILED:', e); process.exit(1); });

